INSERT INTO egon_cola_operation_log (
    id, tenant_id, operation_id, schema_version, source_service, module_code, action_code, resource_type, resource_id, biz_code, namespace_code, env,
    app_code, actor_type, actor_id, actor_name, trigger_type, phase, outcome, reason_code, http_method, request_url, route_pattern, handler_method, trace_id, request_id,
    occurred_at, duration_ms, details, create_user_id, create_time, update_user_id, update_time, version, deleted_at
) VALUES (
    #{et.id}, #{et.tenantId}, #{et.operationId}, #{et.schemaVersion}, #{et.sourceService}, #{et.moduleCode}, #{et.actionCode}, #{et.resourceType}, #{et.resourceId}, #{et.bizCode}, #{et.namespaceCode}, #{et.env}, #{et.appCode}, #{et.actorType}, #{et.actorId}, #{et.actorName}, #{et.triggerType}, #{et.phase}, #{et.outcome}, #{et.reasonCode}, #{et.httpMethod}, #{et.requestUrl}, #{et.routePattern}, #{et.handlerMethod}, #{et.traceId}, #{et.requestId}, #{et.occurredAt}, #{et.durationMs}, #{et.details,jdbcType=OTHER,typeHandler=top.egon.cola.component.common.mybatis.operationlog.OperationLogPO$JsonbTypeHandler}, #{et.createUserId}, #{et.createTime}, #{et.updateUserId}, #{et.updateTime}, #{et.version}, #{et.deletedAt}
)

mapper.select:
SELECT id, tenant_id, operation_id, occurred_at, source_service, module_code,
    action_code, resource_type, resource_id, actor_type, actor_id, actor_name,
    phase, outcome, route_pattern
FROM egon_cola_operation_log
WHERE tenant_id = #{query.tenantId} AND deleted_at IS NULL
    AND occurred_at >= #{query.from} AND occurred_at < #{query.to}
AND action_code = #{query.filters.actionCode}
AND actor_id = #{query.filters.actorId}
AND resource_type = #{query.filters.resourceType}
AND resource_id = #{query.filters.resourceId}
AND biz_code = #{query.filters.bizCode}
AND namespace_code = #{query.filters.namespaceCode}
AND env = #{query.filters.env}
AND app_code = #{query.filters.appCode}
AND outcome = #{query.filters.outcome}

    AND (occurred_at < #{query.beforeTime}
        OR (occurred_at = #{query.beforeTime} AND id < #{query.beforeId}))

ORDER BY occurred_at DESC, id DESC
LIMIT #{query.fetchLimit}
